#pragma once
#include <concepts>
#include <cstdint>
#include <string>
#include <string_view>
#include <netinet/in.h>

namespace ws {

class IPAddr {
public:
    virtual ~IPAddr() noexcept = default;
    virtual int Version() const noexcept = 0;
    virtual std::size_t Size() const noexcept = 0;
    virtual const sockaddr* Raw() const noexcept = 0;
    virtual std::uint16_t Port() const noexcept = 0;
    virtual std::string IPAddress() const noexcept = 0;
};

class IPv4Addr final : public IPAddr {
public:
    static constexpr int version{AF_INET};
    static constexpr std::string_view loop_back{"127.0.0.1"};
    static constexpr std::string_view any{"0.0.0.0"};
    static constexpr std::size_t max_length{15};

    using RawType = sockaddr_in;

    explicit IPv4Addr(sockaddr_in addr) {
        char buf[INET_ADDRSTRLEN];
        if (inet_ntop(AF_INET, &addr.sin_addr, buf, sizeof(buf)) == nullptr) {
            ThrowLastSystemError();
        }
        ip_ = buf;
        raw_ = addr;
    }

    explicit IPv4Addr(std::string ip, std::uint16_t port) {
        raw_.sin_family = AF_INET;
        raw_.sin_port = htons(port);
        if (inet_pton(AF_INET, ip.c_str(), &raw_.sin_addr) != 1) {
            ThrowLastSystemError();
        }
        ip_ = std::move(ip);
    }

    int Version() const noexcept override { return version; }
    std::size_t Size() const noexcept override { return sizeof(raw_); }
    const sockaddr* Raw() const noexcept override { return reinterpret_cast<const sockaddr*>(&raw_); }
    std::uint16_t Port() const noexcept override { return ntohs(raw_.sin_port); }
    std::string IPAddress() const noexcept override { return ip_; }

private:
    std::string ip_;
    RawType raw_{};
};

class IPv6Addr final : public IPAddr {
public:
    static constexpr int version{AF_INET6};
    static constexpr std::string_view loop_back{"::1"};
    static constexpr std::string_view any{"::"};
    static constexpr std::size_t max_length{45};

    using RawType = sockaddr_in6;

    explicit IPv6Addr(sockaddr_in6 addr) {
        char buf[INET6_ADDRSTRLEN];
        if (inet_ntop(AF_INET6, &addr.sin6_addr, buf, sizeof(buf)) == nullptr) {
            ThrowLastSystemError();
        }
        ip_ = buf;
        raw_ = addr;
    }

    explicit IPv6Addr(std::string ip, std::uint16_t port) {
        raw_.sin6_family = AF_INET6;
        raw_.sin6_port = htons(port);
        if (inet_pton(AF_INET6, ip.c_str(), &raw_.sin6_addr) != 1) {
            ThrowLastSystemError();
        }
        ip_ = std::move(ip);
    }

    int Version() const noexcept override { return version; }
    std::size_t Size() const noexcept override { return sizeof(raw_); }
    const sockaddr* Raw() const noexcept override { return reinterpret_cast<const sockaddr*>(&raw_); }
    std::uint16_t Port() const noexcept override { return ntohs(raw_.sin6_port); }
    std::string IPAddress() const noexcept override { return ip_; }

private:
    std::string ip_;
    RawType raw_{};
};

template <typename T>
concept ValidIPAddr = std::same_as<T, IPv4Addr> || std::same_as<T, IPv6Addr>;

} // namespace ws

#pragma once
#include <stdexcept>
#include <system_error>

namespace ws {

[[noreturn]] inline void ThrowLastSystemError() {
    throw std::system_error(std::error_code(errno, std::generic_category()), "System error occurred");
}

} // namespace ws
